namespace sv_2950b51d17fa49008f4ad77145568532.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_2950b51d17fa49008f4ad77145568532.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

@if (isLoading && searchResult is null)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else
{
    <div class="row">
        @* ── Left Sidebar (Filters) ── *@
        <div class="col-lg-3 mb-4">
            <div class="card">
                <div class="card-header fw-bold">Filters</div>
                <div class="card-body">
                    @* Category checkboxes *@
                    <h6>Category</h6>
                    @if (categories is not null)
                    {
                        @foreach (var cat in categories)
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="cat-@cat"
                                       checked="@selectedCategories.Contains(cat)"
                                       @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                                <label class="form-check-label" for="cat-@cat">@cat</label>
                            </div>
                        }
                    }

                    <hr />

                    @* Price range *@
                    <h6>Price Range</h6>
                    <div class="mb-2">
                        <label class="form-label form-label-sm" for="minPrice">Min</label>
                        <input id="minPrice" type="number" class="form-control form-control-sm"
                               min="0" step="0.01" placeholder="0.00" @bind="minPrice" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label form-label-sm" for="maxPrice">Max</label>
                        <input id="maxPrice" type="number" class="form-control form-control-sm"
                               min="0" step="0.01" placeholder="Any" @bind="maxPrice" />
                    </div>

                    <hr />

                    @* In Stock Only *@
                    <div class="form-check form-switch mb-3">
                        <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="inStockOnly" />
                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                    </div>

                    @* Action buttons *@
                    <div class="d-grid gap-2">
                        <button class="btn btn-primary btn-sm" @onclick="ApplyFiltersAsync" disabled="@isLoading">
                            Apply Filters
                        </button>
                        <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFiltersAsync" disabled="@isLoading">
                            Clear Filters
                        </button>
                    </div>
                </div>
            </div>
        </div>

        @* ── Main Content ── *@
        <div class="col-lg-9">
            @* Toolbar *@
            <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                <div>
                    <label class="form-label form-label-sm mb-0 me-1" for="sortSelect">Sort by:</label>
                    <select id="sortSelect" class="form-select form-select-sm d-inline-block w-auto"
                            @onchange="OnSortChangedAsync" value="@sortBy">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>

                @if (searchResult is not null && searchResult.TotalCount > 0)
                {
                    var first = (searchResult.Page - 1) * searchResult.PageSize + 1;
                    var last = Math.Min(searchResult.Page * searchResult.PageSize, searchResult.TotalCount);
                    <span class="text-muted small">Showing @first–@last of @searchResult.TotalCount products</span>
                }
            </div>

            @if (isLoading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else if (searchResult is null || searchResult.Items.Count == 0)
            {
                <div class="alert alert-info text-center" role="alert">
                    No products found matching your filters.
                </div>
            }
            else
            {
                @* Product grid *@
                <div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-3 mb-4">
                    @foreach (var product in searchResult.Items)
                    {
                        <div class="col">
                            <div class="card h-100 product-card" role="button"
                                 @onclick="() => OnProductSelected.InvokeAsync(product.Id)"
                                 style="cursor:pointer;">
                                <div class="card-img-top bg-secondary bg-opacity-25 d-flex align-items-center justify-content-center"
                                     style="height:160px;" title="@product.Name">
                                    <span class="text-muted small">@product.Name</span>
                                </div>
                                <div class="card-body d-flex flex-column">
                                    <h6 class="card-title">@product.Name</h6>
                                    <p class="card-text fw-bold text-primary mb-1">@product.Price.ToString("C")</p>
                                    <p class="card-text mb-1">@GetStarRating(product.Rating)</p>
                                    @if (!product.InStock)
                                    {
                                        <span class="badge bg-danger mb-2">Out of Stock</span>
                                    }
                                    <div class="mt-auto">
                                        <button class="btn btn-sm btn-success w-100"
                                                disabled="@(!product.InStock)"
                                                @onclick="() => { }" @onclick:stopPropagation="true">
                                            Add to Cart
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    }
                </div>

                @* Pagination *@
                @{
                    var totalPages = (int)Math.Ceiling((double)searchResult.TotalCount / searchResult.PageSize);
                }
                @if (totalPages > 1)
                {
                    <nav aria-label="Product pagination">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(currentPage <= 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(currentPage - 1)"
                                        disabled="@(currentPage <= 1)">Previous</button>
                            </li>
                            @for (var p = 1; p <= totalPages; p++)
                            {
                                var pageNum = p;
                                <li class="page-item @(pageNum == currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPageAsync(pageNum)">@pageNum</button>
                                </li>
                            }
                            <li class="page-item @(currentPage >= totalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(currentPage + 1)"
                                        disabled="@(currentPage >= totalPages)">Next</button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </div>
    </div>
}

@code {
    [Parameter] public EventCallback<int> OnProductSelected { get; set; }

    private List<string>? categories;
    private PagedResult<Product>? searchResult;

    // Filter state
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    // Paging & sorting
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 9;

    // UI state
    private bool isLoading;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = ExecuteSearchAsync();

            categories = await categoriesTask;
            await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task ExecuteSearchAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            searchResult = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFiltersAsync()
    {
        currentPage = 1;
        await ExecuteSearchAsync();
    }

    private async Task ClearFiltersAsync()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        sortBy = "price_asc";
        await ExecuteSearchAsync();
    }

    private async Task OnSortChangedAsync(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await ExecuteSearchAsync();
    }

    private async Task GoToPageAsync(int page)
    {
        currentPage = page;
        await ExecuteSearchAsync();
    }

    private async Task RetryAsync()
    {
        await LoadDataAsync();
    }

    private static string GetStarRating(double rating)
    {
        var rounded = (int)Math.Round(rating);
        return new string('★', rounded) + new string('☆', 5 - rounded);
    }
}

